/// ルート行のフォーマット
fn format_root_line(config: &TreeConfig) -> String {
    let folder_name = config
        .target_path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(".");

    let base = if config.classic_mode {
        folder_name.to_string()
    } else if config.show_icons {
        format!("\x1b[1;34m📁 {}\x1b[0m", folder_name)
    } else {
        format!("\x1b[1;34m{}\x1b[0m", folder_name)
    };

    if config.show_dir_sizes {
        let (total_size, total_files) = calculate_dir_summary(&config.target_path, config);
        if config.classic_mode {
            format!(
                "{} [{} files, {}]",
                base,
                total_files,
                format_byte_size(total_size)
            )
        } else {
            format!(
                "{} \x1b[90m[{} files, {}]\x1b[0m",
                base,
                total_files,
                format_byte_size(total_size)
            )
        }
    } else {
        base
    }
}

/// 指定ディレクトリ配下の全ファイルの合計サイズおよびファイル数を再帰的に集計する
fn calculate_dir_summary(dir: &Path, config: &TreeConfig) -> (u64, usize) {
    let mut total_size = 0u64;
    let mut total_files = 0usize;

    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let file_name = entry.file_name().to_string_lossy().into_owned();

            // 隠しファイルのフィルタ
            if file_name.starts_with('.') && !config.show_hidden {
                continue;
            }

            // 除外パターンのフィルタ (ワイルドカード対応)
            let is_excluded = config
                .exclude_patterns
                .iter()
                .any(|pattern| match_wildcard(pattern, &file_name));
            if is_excluded {
                continue;
            }

            let path = entry.path();
            if path.is_dir() {
                let (sub_size, sub_files) = calculate_dir_summary(&path, config);
                total_size += sub_size;
                total_files += sub_files;
            } else {
                total_files += 1;
                if let Ok(metadata) = entry.metadata() {
                    total_size += metadata.len();
                }
            }
        }
    }

    (total_size, total_files)
}

/// 再帰的なツリー構築コア処理
fn print_tree(
    dir: &Path,
    current_depth: usize,
    prefixes: &mut Vec<&str>,
    config: &TreeConfig,
    dir_count: &mut usize,
    file_count: &mut usize,
) {
    // 深度制限のチェック
    if config.max_depth > 0 && current_depth >= config.max_depth {
        return;
    }

    // ディレクトリのエントリを読み込む
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return, // 権限エラーなどはスキップ
    };

    // エントリを一度ベクターに詰める
    let mut valid_entries = Vec::new();
    for entry in entries.flatten() {
        let file_name = entry.file_name().to_string_lossy().into_owned();

        // 隠しファイルのフィルタ
        if file_name.starts_with('.') && !config.show_hidden {
            continue;
        }

        // 除外パターンのフィルタ (ワイルドカード対応)
        let is_excluded = config
            .exclude_patterns
            .iter()
            .any(|pattern| match_wildcard(pattern, &file_name));
        if is_excluded {
            continue;
        }

        valid_entries.push(entry);
    }

    // ソート処理 (ディレクトリを優先ソート)
    valid_entries.sort_by(|a, b| {
        let name_a = a.file_name();
        let name_b = b.file_name();

        let is_dir_a = a.path().is_dir();
        let is_dir_b = b.path().is_dir();

        if is_dir_a != is_dir_b {
            if is_dir_a {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Greater
            }
        } else {
            name_a.cmp(&name_b)
        }
    });

    let count = valid_entries.len();
    for (idx, entry) in valid_entries.iter().enumerate() {
        let is_last = idx == count - 1;
        let path = entry.path();
        let is_directory = path.is_dir();
        let file_name = entry.file_name().to_string_lossy().into_owned();

        // 1. インデント接頭辞の出力
        for pref in prefixes.iter() {
            print!("{}", pref);
        }

        // 2. ブランチ記号の決定
        let branch = if config.classic_mode {
            if is_last {
                "\\-- "
            } else {
                "+-- "
            }
        } else if is_last {
            "└── "
        } else {
            "├── "
        };
        print!("{}", branch);

        // 3. アイコン絵文字の出力 (有効な場合)
        if config.show_icons {
            print!("{} ", icon::get_icon_emoji(&file_name, is_directory));
        }

        // 4. 名前と各種メタ情報の出力
        if is_directory {
            *dir_count += 1;
            if config.classic_mode {
                print!("{}", file_name);
            } else {
                // ディレクトリは青字・太字
                print!("\x1b[1;34m{}\x1b[0m", file_name);
            }

            // ディレクトリ配下の集計情報表示 (-D / --dir-sizes 有効時)
            if config.show_dir_sizes {
                let (total_size, total_files) = calculate_dir_summary(&path, config);
                if config.classic_mode {
                    print!(" [{} files, {}]", total_files, format_byte_size(total_size));
                } else {
                    print!(
                        " \x1b[90m[{} files, {}]\x1b[0m",
                        total_files,
                        format_byte_size(total_size)
                    );
                }
            }
        } else {
            *file_count += 1;
            // 通常のファイル
            print!("{}", file_name);

            // ファイルサイズ表示
            if config.show_sizes {
                if let Ok(metadata) = entry.metadata() {
                    let size = metadata.len();
                    if config.classic_mode {
                        print!(" [{}]", format_byte_size(size));
                    } else {
                        print!(" \x1b[90m[{}]\x1b[0m", format_byte_size(size));
                    }
                }
            }
        }
        println!();

        // ディレクトリの場合は再帰呼び出し
        if is_directory {
            let next_prefix = if config.classic_mode {
                if is_last {
                    "    "
                } else {
                    "|   "
                }
            } else if is_last {
                "    "
            } else {
                "│   "
            };
            prefixes.push(next_prefix);
            print_tree(
                &path,
                current_depth + 1,
                prefixes,
                config,
                dir_count,
                file_count,
            );
            prefixes.pop();
        }
    }
}

/// ワイルドカード (*, ?) パターンマッチ関数 (依存ライブラリなし)
fn match_wildcard(pattern: &str, text: &str) -> bool {
    let p_chars: Vec<char> = pattern.to_lowercase().chars().collect();
    let t_chars: Vec<char> = text.to_lowercase().chars().collect();

    let mut p_idx = 0;
    let mut t_idx = 0;
    let mut star_idx = None;
    let mut match_t_idx = 0;

    while t_idx < t_chars.len() {
        if p_idx < p_chars.len() && (p_chars[p_idx] == '?' || p_chars[p_idx] == t_chars[t_idx]) {
            p_idx += 1;
            t_idx += 1;
        } else if p_idx < p_chars.len() && p_chars[p_idx] == '*' {
            star_idx = Some(p_idx);
            match_t_idx = t_idx;
            p_idx += 1;
        } else if let Some(s_idx) = star_idx {
            p_idx = s_idx + 1;
            match_t_idx += 1;
            t_idx = match_t_idx;
        } else {
            return false;
        }
    }

    while p_idx < p_chars.len() && p_chars[p_idx] == '*' {
        p_idx += 1;
    }

    p_idx == p_chars.len()
}

/// バイト単位のファイルサイズを読みやすい形式に変換
fn format_byte_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.1} KB", bytes as f64 / 1024.0)
    } else {
        format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0))
    }
}

/// Windows 10/11 コンソールで ANSI エスケープ処理を有効化する
#[cfg(windows)]
fn enable_ansi_support() {
    // Windows APIを動的にロードしてコンソールのモードを書き換える
    // 依存関係を増やさないよう、libc や winapi クレートを使わずに実装
    #[allow(clippy::upper_case_acronyms)]
    type LPDWORD = *mut u32;
    #[allow(clippy::upper_case_acronyms)]
    type HANDLE = *mut std::ffi::c_void;

    const STD_OUTPUT_HANDLE: u32 = -11i32 as u32;
    const ENABLE_VIRTUAL_TERMINAL_PROCESSING: u32 = 0x0004;

    #[link(name = "kernel32")]
    extern "system" {
        fn GetStdHandle(nStdHandle: u32) -> HANDLE;
        fn GetConsoleMode(hConsoleHandle: HANDLE, lpMode: LPDWORD) -> i32;
        fn SetConsoleMode(hConsoleHandle: HANDLE, dwMode: u32) -> i32;
    }

    unsafe {
        let handle = GetStdHandle(STD_OUTPUT_HANDLE);
        if !handle.is_null() {
            let mut mode: u32 = 0;
            if GetConsoleMode(handle, &mut mode as LPDWORD) != 0 {
                SetConsoleMode(handle, mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_format_byte_size() {
        assert_eq!(format_byte_size(0), "0 B");
        assert_eq!(format_byte_size(500), "500 B");
        assert_eq!(format_byte_size(1023), "1023 B");
        assert_eq!(format_byte_size(1024), "1.0 KB");
        assert_eq!(format_byte_size(1536), "1.5 KB");
        assert_eq!(format_byte_size(1048575), "1024.0 KB");
        assert_eq!(format_byte_size(1048576), "1.0 MB");
        assert_eq!(format_byte_size(10485760), "10.0 MB");
    }

    #[test]
    fn test_match_wildcard() {
        assert!(match_wildcard("*.tmp", "temp.tmp"));
        assert!(match_wildcard("*.TMP", "temp.tmp"));
        assert!(match_wildcard("target", "target"));
        assert!(match_wildcard("target", "TARGET"));
        assert!(match_wildcard("build*", "build_out"));
        assert!(match_wildcard("test?.rs", "test1.rs"));
        assert!(!match_wildcard("*.log", "main.rs"));
        assert!(!match_wildcard("test?.rs", "test12.rs"));
    }

    #[test]
    fn test_parse_arguments_errors() {
        let mut config = TreeConfig::default();

        // 未知のオプション
        let args = vec!["MyTree".to_string(), "-x".to_string()];
        assert!(parse_arguments(&args, &mut config).is_err());

        // -d の値欠落
        let args = vec!["MyTree".to_string(), "-d".to_string()];
        assert!(parse_arguments(&args, &mut config).is_err());

        // -d の無効な数値
        let args = vec!["MyTree".to_string(), "-d".to_string(), "abc".to_string()];
        assert!(parse_arguments(&args, &mut config).is_err());

        // -e の値欠落
        let args = vec!["MyTree".to_string(), "-e".to_string()];
        assert!(parse_arguments(&args, &mut config).is_err());

        // 重複ターゲットパス指定
        let args = vec![
            "MyTree".to_string(),
            "./dir1".to_string(),
            "./dir2".to_string(),
        ];
        assert!(parse_arguments(&args, &mut config).is_err());
    }

    #[test]
    fn test_parse_arguments_default() {
        let args = vec!["MyTree".to_string()];
        let mut config = TreeConfig::default();
        assert!(parse_arguments(&args, &mut config).is_ok());
        assert!(config.show_icons);
        assert!(config.show_sizes);
        assert!(!config.show_hidden);
        assert_eq!(config.max_depth, 0);
    }

    #[test]
    fn test_parse_arguments_custom() {
        let args = vec![
            "MyTree".to_string(),
            "-a".to_string(),
            "-d".to_string(),
            "3".to_string(),
            "-e".to_string(),
            "target,node_modules".to_string(),
        ];
        let mut config = TreeConfig::default();
        assert!(parse_arguments(&args, &mut config).is_ok());
        assert!(config.show_hidden);
        assert_eq!(config.max_depth, 3);
        assert_eq!(config.exclude_patterns, vec!["target", "node_modules"]);
    }

    #[test]
    fn test_parse_arguments_no_icons_sizes() {
        let args = vec!["MyTree".to_string(), "-I".to_string(), "-S".to_string()];
        let mut config = TreeConfig::default();
        assert!(parse_arguments(&args, &mut config).is_ok());
        assert!(!config.show_icons);
        assert!(!config.show_sizes);
    }

    #[test]
    fn test_parse_arguments_dir_sizes() {
        let args = vec!["MyTree".to_string(), "-D".to_string()];
        let mut config = TreeConfig::default();
        assert!(parse_arguments(&args, &mut config).is_ok());
        assert!(config.show_dir_sizes);
    }

    #[test]
    fn test_parse_arguments_classic() {
        let args = vec!["MyTree".to_string(), "-c".to_string()];
        let mut config = TreeConfig::default();
        assert!(parse_arguments(&args, &mut config).is_ok());
        assert!(config.classic_mode);
        assert!(!config.show_icons);
        assert!(!config.show_sizes);
    }

    #[test]
    fn test_calculate_dir_summary() {
        let config = TreeConfig::default();
        let (size, files) = calculate_dir_summary(Path::new("."), &config);
        assert!(files > 0);
        assert!(size > 0);
    }

    #[test]
    fn test_version_env() {
        assert!(!env!("CARGO_PKG_VERSION").is_empty());
    }
}
